receipts = {}
for path in sorted(r.OUTPUT.glob('*.json')):
    if path.name.endswith('-binding.json'):
        continue
    value = json.loads(path.read_text())
    if 'exit_code' not in value:
        continue
    binding_path = r.OUTPUT/(path.stem+'-binding.json')
    log_path = r.OUTPUT/(path.stem+'.log')
    assert r.sha(binding_path) == value['binding_sha256'] and r.sha(log_path) == value['log_sha256']
    assert value['all_commands_terminal'] and not value['remaining_group_members']
    receipts[path.stem] = {'receipt_path':str(path),'receipt_sha256':r.sha(path),'binding_path':str(binding_path),'binding_sha256':value['binding_sha256'],'log_path':str(log_path),'log_sha256':value['log_sha256'],'argv':value['argv'],'cwd':value['cwd'],'exit_code':value['exit_code'],'child_returncode':value['child_returncode'],'start_utc':value['start_utc'],'end_utc':value['end_utc'],'elapsed_seconds':value['elapsed_seconds'],'timed_out':value['timed_out'],'process_group':value['process_group'],'all_commands_terminal':value['all_commands_terminal']}
